def validate_audit(root, request_path, data, require_launch=True):
    """Structural validation complements, never replaces, independent code review."""
    request = read_json(request_path)
    app_root, app = spec(root, request['appSpec'])
    errors = []
    workspace = compute_workspace_fingerprint(root)
    if not fingerprint_equal(request['workspaceFingerprint'], workspace):
        errors.append('audit workspace is stale')
    if not fingerprint_equal(request['appSpecFingerprint'], compute_app_spec_fingerprint(app_root)):
        errors.append('audit AppSpec is stale')
    if data.get('requestSha256') != sha256_bytes(request_path.read_bytes()):
        errors.append('audit request hash mismatch')
    try:
        if not parse_time(request['createdAt']) <= parse_time(data['startedAt']) <= parse_time(data['completedAt']):
            errors.append('invalid audit chronology')
    except (KeyError, ValueError, TypeError):
        errors.append('audit timestamps required')
    sources = {p.relative_to(app_root).as_posix() for p in app_root.rglob('*.md')}
    if not sources.issubset(set(data.get('reviewedSources', []))):
        errors.append('review all normative AppSpec sources, including flows/screens')
    if data.get('inventory') != canonical_inventory(app):
        errors.append('independent inventory mismatch')
    if require_launch:
        launch_path = request_path.with_name('launch.json')
        launch = read_json(launch_path) if launch_path.exists() else {}
        events_path = request_path.with_name('events.jsonl')
        prompt_path = request_path.with_name('prompt.txt')
        if (launch.get('producer') != 'vibe-lean-audit-runner' or launch.get('exitCode') != 0
                or launch.get('executionStatus') != 'completed' or not launch.get('threadId')
                or launch.get('requestSha256') != sha256_bytes(request_path.read_bytes())):
            errors.append('successful independent audit launch required')
        if not events_path.exists() or launch.get('eventsSha256') != sha256_bytes(events_path.read_bytes()):
            errors.append('audit host event log mismatch')
        else:
            try:
                ids = [e.get('thread_id') for line in events_path.read_text(encoding='utf-8').splitlines()
                    if line.strip() for e in [json.loads(line)] if e.get('type') == 'thread.started']
                if ids != [launch.get('threadId')]: errors.append('audit host thread mismatch')
            except ValueError: errors.append('invalid audit events')
        if not prompt_path.exists() or launch.get('promptSha256') != sha256_bytes(prompt_path.read_bytes()):
            errors.append('audit prompt hash mismatch')
        for key in ('startWorkspaceFingerprint', 'workspaceFingerprint'):
            if not fingerprint_equal(launch.get(key), request['workspaceFingerprint']):
                errors.append('audit source changed during execution')
        prior = request.get('previousAudit')
        if prior and launch.get('threadId') != prior['threadId']:
            errors.append('delta review must use the same independent auditor')
    surfaces = verification_surface_map(app)
    expected = {(oid, s) for oid, values in surfaces.items() for s in values}
    unavailable = {(r['obligationId'], r['surface']) for r in request['unavailablePairs']
        if requires_native_host(r['surface']) and r.get('reason') and r.get('prerequisites')}
    categories = {g['id']: g['category'] for g in app['qualityGates']}
    conditional = {g['id'] for g in app['qualityGates']
        if g.get('requirement') == 'conditional' and g.get('condition')}
    latest = {}
    for path in (root / '.vibe/receipts').glob('*.json'):
        receipt = read_json(path)
        if fingerprint_equal(receipt.get('workspaceFingerprint'), workspace):
            key = tuple(receipt.get('argv', []))
            if receipt.get('completedAt', '') > latest.get(key, {}).get('completedAt', ''):
                latest[key] = receipt
    checked_receipts = set()
    rows = data.get('obligations', [])
    seen = set(); gaps = []; incomplete = []
    for row in rows:
        pair = (row.get('id'), row.get('surface'))
        if pair not in expected or pair in seen:
            errors.append(f'invalid/duplicate obligation pair: {pair}')
        seen.add(pair)
        result = row.get('result')
        if result == 'verified':
            if row.get('auditEvidence') is True:
                if pair[0] not in categories or pair[1] not in {'independent-audit', 'acceptance-audit', 'audit'} or not row.get('assertion'):
                    errors.append(f'{pair}: invalid self-audit proof')
                continue
            for key in ('production', 'tests'):
                anchors = row.get(key, [])
                if not anchors: errors.append(f'{pair}: {key} anchors required')
                for anchor in anchors:
                    try:
                        path = local(root, anchor['path'])
                        symbol = anchor.get('symbol')
                        if not path.is_file() or not symbol or symbol not in path.read_text(encoding='utf-8'):
                            errors.append(f'{pair}: missing {key} anchor')
                    except (KeyError, OSError, UnicodeError, ProtocolError): errors.append(f'{pair}: invalid anchor')
            if not row.get('assertion') or not row.get('receiptRefs'):
                errors.append(f'{pair}: assertion and executed check required')
            for ref in row.get('receiptRefs', []):
                if ref in checked_receipts: continue
                checked_receipts.add(ref)
                try:
                    receipt_path = local(root, ref)
                    if not receipt_path.is_relative_to(root / '.vibe/receipts'):
                        raise ProtocolError('receipt outside receipts')
                    receipt = read_json(receipt_path)
                    last = latest.get(tuple(receipt.get('argv', [])), receipt)
                    if last.get('exitCode') != 0 or last.get('executionStatus') != 'completed':
                        errors.append(f'{pair}: latest current execution failed: {ref}')
                    log = local(root, receipt['log']['path'])
                    if (receipt.get('exitCode') != 0 or receipt.get('executionStatus') != 'completed'
                            or not fingerprint_equal(receipt.get('workspaceFingerprint'), workspace)
                            or not fingerprint_equal(receipt.get('startWorkspaceFingerprint'), workspace)
                            or not receipt.get('argv') or not log.is_file()
                            or sha256_bytes(log.read_bytes()) != receipt['log']['sha256']):
                        errors.append(f'{pair}: failed/stale check or log: {ref}')
                    if not parse_time(receipt['startedAt']) <= parse_time(receipt['completedAt']) <= parse_time(data['completedAt']):
                        errors.append(f'{pair}: check chronology mismatch')
                except (ProtocolError, OSError, KeyError, ValueError, TypeError):
                    errors.append(f'{pair}: invalid receipt: {ref}')
        elif result == 'unavailable':
            if pair not in unavailable: errors.append(f'{pair}: not a declared host limitation')
            incomplete.append(pair)
        elif result == 'not-applicable':
            if (categories.get(pair[0]) not in {'external', 'release'} or pair[0] not in conditional
                    or not row.get('reason')):
                errors.append(f'{pair}: only inactive external/release conditions may be not-applicable')
        elif result == 'gap':
            if not row.get('reason'): errors.append(f'{pair}: gap reason required')
            gaps.append(pair)
        else:
            errors.append(f'{pair}: unsupported result')
    if seen != expected: errors.append('missing obligation/surface pairs')
    verdict = data.get('verdict')
    if verdict not in {'PASS', 'GAPS', 'BLOCKED'}: errors.append('invalid verdict')
    if verdict == 'PASS' and (gaps or data.get('findings')): errors.append('PASS cannot contain open findings')
    if verdict != 'PASS' and not data.get('findings'): errors.append('non-PASS requires findings')
    return errors, {'locallyVerified': verdict == 'PASS' and not errors,
        'implementationComplete': verdict == 'PASS' and not errors and not incomplete,
        'releaseReady': verdict == 'PASS' and not errors and not incomplete and
            not any(r.get('result') == 'not-applicable' for r in rows)}


